                    continue
                new_s = current_stones - c
                if new_s == 0:
                    return True
                # Opponent's turn
                opponent_playable = [d for d in opponent_cards if d <= new_s]
                if not opponent_playable:
                    return True
                all_ok = True
                for d in opponent_playable:
                    new_ss = new_s - d
                    my_remaining = [x for x in my_cards if x != c]
                    opponent_remaining = [x for x in opponent_cards if x != d]
                    if not can_win(new_ss, my_remaining, opponent_remaining):
                        all_ok = False
                        break
                if all_ok:
                    return True
            return False

        # Find the best card to play
        playable = [c for c in cards if c <= stones]
        if not playable:
            chosen_card = None
        else:
