                    if not can_win(new_s, my_remaining, opponent_remaining_after_d):
                        all_ok = False
                        break
                if all_ok:
                    chosen_card = c
                    break
            if not chosen_card:
                chosen_card = playable[0]

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
