from typing import List, Any

class CardNimCustomStrategy:
    def __init__(self, model: Any):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.initial_cards = None  # To store the initial cards of the player
        self.opponent_played = []  # To track opponent's played cards

    def receive_message(self, message: Any) -> Any:
        # Extract parameters from the message
        cards, stones, opponent_card = message.message[0].data

        # Initialize initial_cards if not already set
        if self.initial_cards is None:
            self.initial_cards = cards.copy()

        # Record the opponent's last played card
        self.opponent_played.append(opponent_card)

        # Calculate opponent's remaining cards
        opponent_initial = self.initial_cards.copy()
        opponent_remaining = opponent_initial.copy()
        for card in self.opponent_played:
            if card in opponent_remaining:
                opponent_remaining.remove(card)

        best_score = -1
        best_card = None

        for c in cards:
            if c > stones:
                continue  # Card is not playable
            new_s = stones - c

            # Find the maximum d the opponent can play
            d_max = -1
            for d in opponent_remaining:
                if d <= new_s and d > d_max:
                    d_max = d

            # Check if opponent can't play any card (all > new_s)
            if d_max == -1 and not any(d <= new_s for d in opponent_remaining):
                # Opponent can't play, so this move makes me win immediately
                chosen_card = c
                return Info(
                    sender=self.__class__.__name__,
                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=chosen_card, type='custom')]
                )

            remaining_after = new_s - d_max if d_max != -1 else new_s  # if d_max is -1, opponent can't play, but we already checked that case above

            # Update best card
            if remaining_after > best_score:
                best_score = remaining_after
                best_card = c

        # If no card leads to a win, choose the best possible based on remaining_after
        if best_card is None:
            # Fallback: choose the smallest playable card
            for c in sorted(cards):
                if c <= stones:
                    best_card = c
                    break

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=best_card, type='custom')]
        )

